def bootstrap_fit(x, y, n_bootstrap=1000, seed=42):
    rng = np.random.RandomState(seed)
    n = len(x)
    alphas = np.zeros(n_bootstrap)
    for i in range(n_bootstrap):
        idx = rng.choice(n, n, replace=True)
        _, alpha, _, _, _ = fit_power_law(x[idx], y[idx], x_range)
        alphas[i] = alpha if alpha is not None else np.nan
    valid = alphas[~np.isnan(alphas)]
    return {'mean': np.mean(valid), 'std': np.std(valid),
            'ci_95': np.percentile(valid, [2.5, 97.5]),
            'median': np.median(valid)}
